package com.nulljosh.nimble

/**
 * The BC driver's knowledge test with no network, from ICBC's guide Learn to Drive Smart: graduated licensing, speed
 * limits, signs and signals, right of way, impairment, sharing the road, parking and emergencies. A port of
 * `driver()` in docs/engine.js; the table is copied from there by script.
 */
internal object Driving {
    /** Phrase questions, matched anywhere, first match wins. */
    private val facts = listOf(
        """\bhow many questions\b.*\bknowledge test\b|\bknowledge test\b.*\bhow many questions\b""" to "50 multiple-choice questions on the Class 7 knowledge test, taken on a computer at an ICBC driver licensing office.",
        """\b(?:score|mark|how many)\b.*\bpass\b.*\bknowledge test\b|\bpass(?:ing)? (?:score|mark)\b.*\bknowledge test\b""" to "40 correct out of 50 (80 percent).",
        """\bclass 5 licen[cs]e\b|\bwhat is (?:a )?class 5\b""" to "BC's full-privilege driver's licence for cars, vans, pickups and motorhomes, earned after the novice stage by passing the Class 5 road test.",
        """\bzero tolerance\b""" to "Learner and novice drivers must have no alcohol or drugs in their body when driving. Any amount brings an immediate roadside prohibition and can extend the graduated licensing period.",
        """\bnovice\b.*\bhands-?free\b|\bhands-?free\b.*\b(?:novice|learner)\b""" to "No. Learner and novice drivers may not use any electronic device while driving, not even hands-free, except to call 911.",
        """\bexcessive speeding\b|\b(?:more than|over) 40 km/?h over\b""" to "Driving more than 40 km/h over the limit is excessive speeding: the vehicle is impounded for at least 7 days on the spot, with a fine of \$368 to \$483 and 3 penalty points.",
        """\bred circle\b.*\b(?:line|slash|stroke)\b""" to "Not allowed: the action shown inside, such as a left turn or a U-turn, is prohibited.",
        """\bpentagon(?:al)?(?:[- ]shaped)? sign\b""" to "A school zone or school crossing ahead.",
        """\btriangle\b.*\bsign\b|\btriangular sign\b""" to "Yield: slow down and give the right of way, stopping if needed.",
        """\bgreen arrow\b""" to "You may turn in the direction of the arrow; oncoming traffic is stopped, so it is a protected turn. Still yield to pedestrians in the crosswalk.",
        """^(?!.*\bflashing\b).*(?:\byellow (?:traffic )?light\b|\bamber light\b)""" to "The light is about to turn red: stop before the stop line if you can do so safely; if you are too close to stop safely, go through with care.",
        """\bpedestrian countdown\b|\bcountdown (?:signal|timer)\b.*\b(?:pedestrian|crosswalk|traffic)\b""" to "The number of seconds left for pedestrians to cross. Do not start crossing once the countdown has begun, and drivers can use it to judge when the light will change.",
        """\bsolid white line\b""" to "Changing lanes across it is discouraged; stay in your lane, such as near intersections and on the approach to them.",
        """\bdiamond\b.*\b(?:lane|symbol)\b|\breserved lane\b""" to "A reserved lane, such as an HOV, bus or bicycle lane, for the vehicles shown on the signs, at the posted times.",
        """\bt[- ]intersection\b""" to "Traffic on the road that ends must yield to traffic on the through road.",
        """\bwhite cane\b|\bguide dog\b""" to "Stop and yield to them: a white cane or guide dog means the pedestrian is blind or has low vision.",
        """\bspeed limit\b.*\bconstruction zone\b|\bconstruction zone\b.*\bspeed\b""" to "The reduced limit posted on the signs, often 30 to 60 km/h, and slower if the traffic control person tells you.",
        """\bconstruction zone\b|\bwork zone\b""" to "Slow to the posted speed, obey the signs and the traffic control person (flagger), stay alert for workers and equipment, and do not change lanes unless told to.",
        """\bstop sign\b.*\bno stop line\b|\bno stop line\b|\bwhere\b.*\bstop\b.*\bstop sign\b""" to "Stop at the stop line; if there is none, before the crosswalk; if there is no crosswalk, before you enter the intersection.",
        """\bat a stop sign\b|\bstop sign\b.*\bwhat (?:should|do) you do\b""" to "Come to a full stop at the stop line (or before the crosswalk or intersection), yield to pedestrians and traffic with the right of way, then go when it is safe.",
        """\bfollowing distance\b.*\bhighway\b|\bhighway\b.*\bfollowing distance\b""" to "At least three seconds on highways and other high-speed roads, two in the city in good conditions, and more in bad weather.",
        """\b(?:cross|crossing)\b.*\bsolid yellow\b|\bsolid yellow\b.*\b(?:cross|when can)\b""" to "Only to turn left into or out of a driveway or road, or to pass a cyclist or an obstruction when it is safe. Never to pass a moving vehicle.",
        """\bright turn\b|\bturn right\b(?!.*\bred\b)""" to "Signal, shoulder check for cyclists, slow down, keep close to the right curb and turn into the right-hand lane, yielding to pedestrians.",
        """\bu-?turns?\b""" to "Make a U-turn only where it is safe and allowed: never where a sign prohibits it, on a curve or hill where you cannot see 150 m both ways, or at an intersection with traffic lights unless a sign permits it.",
        """\bwhen (?:backing up|reversing)(?: (?:a|your|the) (?:car|vehicle))?$|\b(?:back(?:ing)? up|revers\w*)\b.*\b(?:car|vehicle|driv\w*|park\w*)\b""" to "Shoulder check all around, look back through the rear window with your arm over the seat, and back up slowly, never relying on mirrors or the camera alone.",
        """\bpark\b.*\bcurb\b.*\bhow far\b|\bhow far\b.*\bfrom the curb\b|\bdistance from the curb\b""" to "Within 30 cm of the curb, parallel to it.",
        """\bparallel park""" to "Parking in line with the curb, usually between two vehicles: pull up beside the front car, reverse in at an angle, then straighten, ending within 30 cm of the curb.",
        """\bpark\w*\b.*\buphill\b|\buphill\b.*\bpark""" to "With a curb, turn your front wheels away from the curb (to the left) and let the car roll back gently against it. Without a curb, turn them toward the edge of the road. Set the parking brake.",
        """\bpark\w*\b.*\bdownhill\b|\bdownhill\b.*\bpark""" to "Turn your front wheels toward the curb or edge of the road (to the right) and set the parking brake.",
        """\bstall\w*\b.*\b(?:railway|railroad|train|tracks)\b|\b(?:tracks|railway)\b.*\bstall""" to "Get everyone out at once and move well away from the tracks, toward the train at an angle so debris will not hit you, then call the emergency number on the crossing sign or 911.",
        """\baccelerator\b.*\bstick|\bstuck accelerator\b|\bgas pedal\b.*\bstick""" to "Shift to neutral, brake firmly, steer off the road when it is safe, and turn off the engine once stopped.",
        """\btire\b.*\bblow|\bblow-?out\b""" to "Hold the steering wheel firmly and keep going straight, ease off the gas, and do not brake hard; slow down gradually and pull off the road.",
        """\b(?:vehicle|car)\b.*\b(?:into|in) (?:the )?water\b|\bsinking car\b""" to "Seatbelts off, window open (before the water rises), children out first, then get out and swim to safety. Do not wait to open the door or call for help first.",
        """\beffects? of alcohol\b|\balcohol\b.*\baffect\b.*\bdriv""" to "It slows your reaction time and weakens judgement, vision, coordination and concentration, while making you feel more confident, so risk rises sharply even below the legal limit.",
        """\bdrug[- ]impaired\b|\bdriv\w* (?:while )?(?:high|on drugs|stoned)\b|\bcannabis\b.*\bdriv""" to "Driving while your ability is impaired by drugs, including cannabis and some prescription and over-the-counter medicines. Police can test you and issue a 90-day prohibition, and it is a Criminal Code offence.",
        """\b(?:legal )?blood alcohol limit\b.*\b(?:fully licen[cs]ed|class 5|full licen[cs]e)\b|\b(?:fully licen[cs]ed|class 5)\b.*\bblood alcohol\b""" to "0.08 is the criminal limit, but in BC a reading of 0.05 to 0.08 already brings an immediate roadside prohibition. Novice and learner drivers must be at zero.",
        """\b(?:share|sharing)\b.*\bmotorcycles?\b|\bmotorcycles?\b.*\b(?:share|sharing|passing|following)\b""" to "Give motorcycles a full lane, keep at least three seconds of following distance, shoulder check carefully since they are easy to miss, and watch for them at intersections.",
        """\b(?:share|sharing|passing|blind spots?)\b.*\b(?:large trucks?|semis?|big rigs?|commercial trucks?)\b|\b(?:large trucks?|semis?|big rigs?)\b.*\b(?:share|sharing|passing|blind spots?|no-?zones?)\b""" to "Stay out of their blind spots (the no-zones beside, close behind and in front), never cut in front, give them extra room, and watch for wide right turns.",
        """\b(?:driv\w*|speed)\b.*\bfog\b|\bfog\b.*\b(?:driv\w*|speed)\b""" to "Slow down, use low beams (not high beams) and fog lights if you have them, increase your following distance, and pull well off the road if you cannot see.",
        """\btailgat""" to "Do not speed up or brake suddenly: increase the space in front of you, and move over or let them pass when it is safe.",
        """\blicen[cs]e\b.*\bafter\b.*\broad test\b|\bpass(?:ing)? the (?:class 7 )?road test\b.*\blicen[cs]e\b""" to "A Class 7 novice (N) licence. After at least 24 months with no prohibitions (18 if you took an approved course) you take the Class 5 road test for a full licence.",
        """\bhow long\b.*\bnovice\b|\bnovice (?:stage|period)\b.*\bhow long\b""" to "At least 24 months, or 18 with an ICBC-approved driver training course, before the Class 5 road test.",
        """\bpassengers?\b.*\bnovice\b|\bnovice\b.*\bpassengers?\b""" to "One passenger, unless a supervisor 25 or older with a full licence is in the front seat. Immediate family members do not count toward the limit.",
        """\blearner\b.*\bhighway\b|\bhighway\b.*\blearner\b""" to "Yes. Learners may drive on highways with their supervisor; there is no highway ban in BC.",
        """\b(?:over|above) 0?\.08\b|\bfail(?:ed)? (?:a )?breath\b|\bbac (?:over|above) 0?\.08\b""" to "An immediate 90-day driving prohibition, usually a 30-day vehicle impound, about \$3,750 in fines and costs, and the responsible driver program and an ignition interlock. It can also bring criminal charges.",
        """\bwarn range\b|\b0?\.05\b.*\b0?\.08\b""" to "A blood alcohol reading of 0.05 to 0.08 (a \"warn\" on the roadside screening device). First time: a 3-day prohibition; second within five years: 7 days; third: 30 days, with fines.",
        """\bwhite (?:rectangular|rectangle) sign\b|\bregulatory sign\b""" to "A regulatory sign: a rule you must obey, such as a speed limit, a turn restriction or parking rules.",
        """\borange (?:diamond )?sign\b|\bconstruction sign\b""" to "Road construction or maintenance ahead: slow down, obey the traffic control person and watch for workers.",
        """\bgreen sign\b|\bguide sign\b""" to "A guide sign: directions, distances and destinations, such as highway exits.",
        """\byield sign\b""" to "Slow down and give the right of way to traffic and pedestrians, stopping if needed, before you go on.",
        """\bsolid red (?:light|signal)\b|\bred (?:traffic )?light\b.*\bmeans?\b|\bwhat (?:do|should) you do at a red (?:traffic )?light\b""" to "Stop before the stop line, crosswalk or intersection and wait for green. You may turn right (or left onto a one-way street) after a full stop if it is safe and no sign forbids it.",
        """\bturn right on (?:a )?red\b|\bright turn on (?:a )?red\b""" to "Yes, after coming to a full stop and yielding to pedestrians and traffic, unless a sign prohibits it.",
        """\bflashing (?:yellow|amber) arrow\b""" to "You may turn in that direction after yielding to oncoming traffic and pedestrians.",
        """\bbroken white line\b|\bdashed white line\b""" to "It separates lanes going the same direction: you may change lanes when it is safe.",
        """\b(?:double solid yellow|solid double yellow)\b""" to "No passing from either direction.",
        """\buncontrolled intersection\b""" to "Yield to any vehicle already in the intersection, and when two arrive at once, yield to the vehicle on your right.",
        """^(?!.*\bstopped\b).*\b(?:ambulance|fire truck|police car)\b.*\b(?:approach\w*|behind|siren|flashing|coming)\b""" to "Pull over to the right and stop until it passes. Never follow a fire truck or other emergency vehicle responding to a call closer than 150 m.",
        """\b(?:pass|passing)\b.*\bstopped\b.*\b(?:tow truck|police|ambulance|fire|emergency|flashing)\b""" to "Slow Down, Move Over: slow to 70 km/h where the limit is 80 km/h or more, or 40 km/h where it is under 80, and move over if it is safe.",
        """\bfollowing distance\b.*\b(?:bad|poor|wet|winter|weather|rain|snow)\b|\b(?:bad|poor) (?:weather|conditions)\b.*\bfollowing distance\b""" to "At least three to four seconds, more on snow or ice. Double the two-second rule in poor conditions.",
        """\bbehind\b.*\b(?:fire truck|emergency vehicle)\b|\b(?:fire truck|emergency vehicle)\b.*\bbehind\b""" to "At least 150 m.",
        """\bhigh beams?\b.*\bfollowing\b|\bfollowing\b.*\bhigh beams?\b""" to "Within 60 m of a vehicle you are following.",
        """\bpark\b.*\bcrosswalk\b|\bcrosswalk\b.*\bpark""" to "At least 6 m from the approach side of a crosswalk.",
        """\bpark\b.*\bbike lane\b|\bbike lane\b.*\bpark""" to "No. Do not park or stop in a bike lane, and you may only cross one to turn or reach the curb.",
        """\bcyclists?\b.*\b(?:pass|passing|distance|space)\b|\b(?:pass|passing)\b.*\bcyclists?\b""" to "At least 1 m on roads with a limit of 50 km/h or less, and 1.5 m where it is over 50, under BC's minimum passing distance rules from 2024. Change lanes if you can.",
        """\bdistracted driving\b""" to "Driving while your attention is on something else: a phone or other device, eating, grooming or a passenger. In BC using a hand-held device brings a \$368 fine and 4 penalty points.",
        """\bpenalt\w*\b.*\b(?:phone|device)\b|\b(?:phone|device)\b.*\bpenalt""" to "A \$368 fine and 4 penalty points, and a second offence within a year can bring a driving prohibition and higher ICBC premiums.",
        """\b(?:involved in|have|get into) (?:a |an )?(?:collision|crash|accident)\b|\bafter (?:a |an )?(?:collision|crash|accident)\b""" to "Stop, help anyone injured and call 911 if needed, exchange names, addresses, licence and insurance details with the other drivers, and report it to ICBC and to police if anyone is hurt or damage is over \$10,000.",
        """\bhit and run\b""" to "Leaving the scene of a collision without stopping to help and exchange information, a serious offence under the Criminal Code and the Motor Vehicle Act.",
        """\bwhen\b.*\b(?:should|must|do) you signal\b|\bwhen to signal\b""" to "Before every turn, lane change, merge or pull away from a curb, early enough that others can see it, usually about 30 m in the city.",
        """\bmerg\w*\b.*\bhighway\b|\bhighway\b.*\bmerg""" to "Signal, use the acceleration lane to match the speed of highway traffic, shoulder check, and move into a gap without stopping.",
        """\bhov lanes?\b|\bhigh[- ]occupancy vehicle lanes?\b""" to "A high-occupancy vehicle lane, for vehicles carrying the posted number of people, usually two or more, along with buses, motorcycles and some electric vehicles.",
        """\bpass(?:ing)? on the right\b""" to "Only when it is safe and there is room, such as on a road with two or more lanes going your way or when the vehicle ahead is turning left. Never use the shoulder.",
        """\bwinter tires?\b""" to "On most BC highways from October 1 to March 31, where signs say so, and to April 30 on some mountain routes. Winter tires show the mountain-snowflake or M+S symbol with at least 3.5 mm of tread.",
        """\b(?:drowsy|tired|sleepy|fatigued?)\b.*\bdriv|\bdriv\w*\b.*\b(?:drowsy|tired|sleepy)\b""" to "Pull over somewhere safe and rest or nap. Coffee and open windows do not fix fatigue.",
        """\broad rage\b""" to "Aggressive, angry behaviour by a driver, such as tailgating, yelling or cutting others off. Do not respond: stay calm, give them room and report dangerous drivers.",
        """\bdefensive driving\b""" to "Driving so you can anticipate hazards and others' mistakes: scanning ahead, keeping space around your vehicle, and being ready to react safely.",
        """\bblack ice\b""" to "A thin, clear layer of ice on the road that is almost invisible, so the road looks merely wet, common on bridges, overpasses and in shade.",
        """\banimal\b.*\b(?:cross|road)\b|\b(?:deer|moose|elk)\b.*\broad\b""" to "Brake firmly and stay in your lane; do not swerve, which can roll the vehicle or send you into oncoming traffic. Slow down in wildlife areas, especially at dawn and dusk.",
        """\b(?:minimum |youngest )?age\b.*\blearner'?s? (?:licen[cs]e|permit)\b|\bhow old\b.*\blearner'?s?\b""" to "16 in BC. Under 19, a parent or guardian must sign the application.",
        """\bhow long\b.*\blearner'?s? (?:licen[cs]e|stage)\b|\blearner'?s? (?:licen[cs]e|stage)\b.*\bhow long\b""" to "At least 12 months before you can take the Class 7 road test, unless the time is extended by a prohibition.",
        """\bsupervis\w*\b.*\blearner\b|\blearner\b.*\bsupervis""" to "A supervisor who is 25 or older and holds a valid full-privilege licence (Class 1 to 5, not a novice licence), sitting in the front passenger seat.",
        """\bpassengers?\b.*\blearner\b|\blearner\b.*\bpassengers?\b""" to "Up to two passengers, one of whom must be the supervisor.",
        """\b(?:hours|times?|when)\b.*\blearner\b.*\bdrive\b|\blearner\b.*\b(?:hours|curfew|at night)\b""" to "Only between 5 a.m. and 11 p.m. Learners may not drive from 11 p.m. to 5 a.m.",
        """\bsign\b.*\b(?:new|learner|novice) drivers?\b.*\bdisplay\b|\bdisplay\b.*\b(?:l|n) sign\b|\b(?:new|learner|novice) drivers?\b.*\bdisplay\b""" to "An \"L\" sign for learners and an \"N\" sign for novices, displayed on the back of the vehicle where it can be seen.",
        """\bblood alcohol\b.*\b(?:novice|learner|new|n|l|glp)\b|\b(?:novice|learner|new) drivers?\b.*\b(?:alcohol|drink)""" to "Zero. Learner and novice drivers may have no alcohol or drugs in their body at all; any amount brings a 12-hour roadside suspension and a prohibition.",
        """^(?!.*\b(?:outside|highways?|rural)\b).*\b(?:default |normal |usual )?speed limit\b.*\b(?:city|town|cities|municipalit|residential|urban)\b|\b(?:city|town|residential)\b.*\bspeed limit\b""" to "50 km/h in cities and towns unless a sign says otherwise.",
        """\bwhen\b.*\bschool zone\b|\bschool zone\b.*\b(?:hours|times?|when|apply)\b""" to "From 8 a.m. to 5 p.m. on school days, unless the sign shows other times.",
        """\bschool zone\b""" to "30 km/h, from 8 a.m. to 5 p.m. on school days unless the sign says otherwise.",
        """\bwhen\b.*\bplayground zone\b|\bplayground zone\b.*\b(?:hours|times?|when|apply)\b""" to "From dawn to dusk, every day of the year.",
        """\bplayground zone\b""" to "30 km/h, from dawn to dusk every day.",
        """\bspeed limit\b.*\b(?:outside|highway|rural|not posted|unposted)\b|\b(?:highway|rural)\b.*\bspeed limit\b""" to "80 km/h on highways outside cities and towns when no limit is posted.",
        """\b(?:red )?octagon(?:al)? sign\b""" to "Stop: come to a full stop at the line, crosswalk or before the intersection, then go when it is safe.",
        """\b(?:yellow )?diamond[- ]shaped sign\b|\byellow diamond\b""" to "A warning sign: a hazard or change in the road ahead, such as a curve, a merge or a crossing.",
        """\bflashing red (?:light|signal)\b""" to "Treat it as a stop sign: stop completely, then go when it is safe.",
        """\bflashing yellow (?:light|signal)\b""" to "Caution: slow down and proceed carefully, watching for hazards.",
        """\bsolid yellow line\b""" to "A solid yellow line on your side of the centre line means no passing.",
        """\bfour[- ]way stop\b|\b4[- ]way stop\b|\ball[- ]way stop\b""" to "The first vehicle to stop goes first. If two arrive at the same time, the driver on the left yields to the vehicle on the right.",
        """\b(?:siren|emergency vehicle)\b""" to "Pull over to the right side of the road and stop, clear of intersections, until it has passed. Never follow an emergency vehicle closer than 150 m.",
        """\bslow down,? move over\b""" to "When you approach a stopped vehicle with flashing red, blue or yellow lights (police, fire, ambulance, tow trucks, road crews), slow to 70 km/h where the limit is 80 km/h or more, or to 40 km/h where it is under 80, and move over to the other lane if it is safe.",
        """\bschool bus\b.*\b(?:flashing|red lights?)\b|\b(?:flashing|red lights?)\b.*\bschool bus\b""" to "Stop, whichever direction you are coming from, and wait until the red lights stop flashing and the stop arm folds.",
        """\btwo[- ]second rule\b|\b2[- ]second rule\b""" to "Keep at least two seconds of following distance behind the vehicle ahead in good conditions: when it passes a fixed point, you should take two seconds to reach that point. Leave more in rain, snow, darkness or at high speed.",
        """\b(?:use|turn on)\b.*\bheadlights\b|\bheadlights\b.*\b(?:when|required)\b""" to "From half an hour after sunset to half an hour before sunrise, and any time you cannot clearly see people or vehicles 150 m ahead, such as in rain, fog or snow.",
        """\bhigh beams?\b.*\boncoming\b|\boncoming\b.*\bhigh beams?\b""" to "Within 150 m of an oncoming vehicle.",
        """\bpark\b.*\bfire hydrant\b|\bfire hydrant\b.*\bpark""" to "At least 5 m away from a fire hydrant.",
        """\bpark\b.*\brail(?:way|road) crossing\b|\brail(?:way|road) crossing\b.*\bpark""" to "At least 15 m from the nearest rail of a railway crossing.",
        """\b(?:hand-?held|cell|mobile) (?:cell )?(?:phone|device)\b.*\bdriv|\bdriv\w*\b.*\b(?:hand-?held|cell|mobile) (?:phone|device)\b|\btext(?:ing)? (?:while|and) driving\b""" to "No. Using a hand-held electronic device while driving is illegal in BC, even stopped at a light: a \$368 fine and 4 penalty points. Learner and novice drivers may not use any device, even hands-free.",
        """\bimmediate roadside prohibition\b|\birp\b""" to "A roadside driving ban for alcohol: a \"warn\" reading (0.05 to 0.08 blood alcohol) brings a 3-, 7- or 30-day prohibition; a \"fail\" (over 0.08) or refusing to blow brings a 90-day prohibition, with fines and possible impoundment.",
        """\bflashing green (?:light|signal)\b""" to "A pedestrian-controlled signal: the light stays flashing green for traffic until a pedestrian pushes the button. You may go through, or turn when it is safe, yielding to pedestrians.",
        """\bpedestrian'?s? right of way\b|\bright of way\b.*\b(?:crosswalk|pedestrian)\b|\bcrosswalk\b.*\bright of way\b""" to "Drivers must yield to pedestrians in a crosswalk, marked or unmarked, and stop if they are in your half of the road or close to it.",
        """\bturn left\b.*\bintersection\b|\bleft turn\b.*\bintersection\b|\bhow (?:to|do you) (?:make a |turn )?left\b""" to "Signal, move to the left side of your lane, yield to oncoming traffic and pedestrians, and turn into the nearest lane going your way.",
        """\broundabouts?\b""" to "Slow down, yield to traffic already in the roundabout (coming from your left), drive counterclockwise, and signal right before your exit.",
        """\brail(?:way|road) crossing\b.*\b(?:flashing|lights|bells|gates?)\b|\b(?:flashing|lights|gates?)\b.*\brail(?:way|road) crossing\b""" to "Stop at least 5 m from the nearest rail and wait until the lights stop flashing and the gates are up, then cross when it is safe.",
        """\bbooster seats?\b""" to "Until the child is 9 years old or 145 cm (4 feet 9 inches) tall, whichever comes first, after they outgrow a forward-facing car seat.",
        """\b(?:vehicle|car)\b.*\bskid|\bskid\w*\b.*\bwhat (?:should|do) you do\b|\bif you skid\b""" to "Ease off the gas and the brake, look where you want to go, and steer smoothly that way. Do not slam on the brakes.",
        """\bbrakes? fail""" to "Pump the brake pedal, shift to a lower gear, and apply the parking brake gradually, steering to a safe place off the road.",
        """\bhydroplan\w*\b""" to "When a layer of water builds up between the tires and the road at speed, so the tires lose contact and you can no longer steer or brake well. Ease off the gas, keep the wheel straight and do not brake hard.",
        """^(?!.*\b(?:eye|eyes|retina|optic)\b).*\bblind spots?\b""" to "Areas around your vehicle you cannot see in your mirrors. Check them with a shoulder check before changing lanes, merging or pulling out.",
        """\bshoulder check\w*\b""" to "Turning your head to look over your shoulder, through the side window, to see the blind spot before you change lanes, merge, pull out or turn.",
    ).map { Regex(it.first) to it.second }

    fun answer(q: String): Answer? {
        for ((re, body) in facts) if (re.containsMatchIn(q)) return Answer.Text(heading = null, body = body, source = "Nimble driving")
